-- The looks show in mod-transmog-plus's Transmogrify window. That module owns the table; it is
-- made here too so this file applies whichever of the two comes first.
CREATE TABLE IF NOT EXISTS `mod_transmog_plus_forms` (
    `DisplayId` int(10) unsigned NOT NULL COMMENT 'CreatureDisplayInfo id from the client patch',
    `Form` varchar(16) NOT NULL COMMENT 'bear, cat, travel, aquatic, flight, moonkin or tree',
    `Name` varchar(80) NOT NULL,
    `UnlockPhase` tinyint(3) unsigned NOT NULL DEFAULT 0 COMMENT 'individual progression phase cleared (quest 66000+n); 0 = from the start',
    `PreviewCreature` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'creature_template entry with this display, for the addon preview',
    `SortOrder` int(10) unsigned NOT NULL DEFAULT 0,
    PRIMARY KEY (`DisplayId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
DELETE FROM `mod_transmog_plus_forms` WHERE `Form` IN ('cat') AND `PreviewCreature` BETWEEN 9505000 AND 9505499;

-- Preview creatures, in 9505000-9505499 with subname 'Druid Form': never spawned.
DELETE m FROM `creature_template_model` m JOIN `creature_template` t ON t.`entry` = m.`CreatureID`
WHERE t.`entry` BETWEEN 9505000 AND 9505499 AND t.`subname` = 'Druid Form';
DELETE t FROM `creature_template` t WHERE t.`entry` BETWEEN 9505000 AND 9505499 AND t.`subname` = 'Druid Form';

-- The patch's CreatureDisplayInfo and CreatureModelData rows, for the server's DBC stores.
DELETE FROM `creaturedisplayinfo_dbc` WHERE `ID` BETWEEN 95900 AND 95903;
DELETE FROM `creaturemodeldata_dbc` WHERE `ID` BETWEEN 95900 AND 95900;
DELETE FROM `creature_model_info` WHERE `DisplayID` BETWEEN 95900 AND 95903;
